// --- context helpers: use the file store when settings.js provides one, ---
// --- otherwise fall back to memory without throwing.                    ---
function put (k, v) { try { flow.set(k, v, 'file') } catch (e) { flow.set(k, v) } }
function get (k, d) {
  let v; try { v = flow.get(k, 'file') } catch (e) { v = undefined }
  if (v === undefined) v = flow.get(k)
  return v === undefined ? d : v
}

// Drops the tick when the circuit breaker is open, when we are inside a
// backoff window, or when Bluetooth has been handed to the phone.
const now = Date.now()
const conn = get('conn', { fails: 0, backoffUntil: 0, breaker: 'closed',
                           reconnects: 0, lastOk: 0, latency: [] })
const forced = msg.topic === 'force'

if (!forced) {
  const hold = Math.max(get('bleReleaseUntil', 0), global.get('bleReleaseUntil') || 0)
  if (hold > now) {
    node.status({ fill: 'grey', shape: 'ring',
                  text: 'Bluetooth released ' + Math.ceil((hold - now) / 1000) + 's' })
    return null
  }
  if (conn.backoffUntil > now) {
    node.status({ fill: 'yellow', shape: 'ring',
                  text: 'backoff ' + Math.ceil((conn.backoffUntil - now) / 1000) + 's' })
    return null
  }
}
node.status({ fill: 'blue', shape: 'dot', text: 'reading' })
flow.set('pollStartedAt', now)
flow.set('pollBusy', true)        // cleared by Normalise / Read failed
// A read-back after a write names the topics it touched; the scheduled
// poll passes an empty payload, which reads the whole tree.
if (!Array.isArray(msg.payload)) delete msg.payload   // use the node's topic list
return msg

// --- context helpers: use the file store when settings.js provides one, ---
// --- otherwise fall back to memory without throwing.                    ---
function put (k, v) { try { flow.set(k, v, 'file') } catch (e) { flow.set(k, v) } }
function get (k, d) {
  let v; try { v = flow.get(k, 'file') } catch (e) { v = undefined }
  if (v === undefined) v = flow.get(k)
  return v === undefined ? d : v
}

// The dashboard's ui-control node reports 'connect' when a browser opens
// the dashboard and 'change' for every page it shows (the first one too).
// Whoever opens the dashboard should not sit on data that is up to two
// minutes old, so ask the poller for a read straight away: the same
// { topic: 'force' } the "Read the heater now" button sends.
const ev = msg.payload
if (ev !== 'connect' && ev !== 'change') return null      // 'lost' etc.
const page = msg.name ? ' (' + msg.name + ')' : ''
const now = Date.now()
const conn = get('conn', {})

// Damping: at most one read per 30 s, whatever the browsers do. A page
// reload, or two phones opening at the same time, must not turn into a
// burst of Bluetooth reads. A read that finished less than 30 s ago
// counts as well: that data is fresh enough.
const DAMP = 30000
const last = Math.max(flow.get('pageOpenPollAt') || 0, conn.lastOk || 0)
if (now - last < DAMP) {
  node.status({ fill: 'grey', shape: 'ring', text: 'read ' + Math.round((now - last) / 1000) + 's ago, skipped' })
  return null
}

// Nothing to do while a read is already running (60 s cap in case a read
// never reports back at all).
const started = flow.get('pollStartedAt') || 0
if (flow.get('pollBusy') && now - started < 60000) {
  node.status({ fill: 'grey', shape: 'ring', text: 'read in progress, skipped' })
  return null
}

// Nothing to do while Bluetooth is handed to the phone. Poll guard lets a
// forced read through that hold on purpose (the Diagnostics button), so
// the hold has to be respected here.
const hold = Math.max(get('bleReleaseUntil', 0), global.get('bleReleaseUntil') || 0)
if (hold > now) {
  node.status({ fill: 'grey', shape: 'ring', text: 'Bluetooth released, skipped' })
  return null
}

flow.set('pageOpenPollAt', now)
node.status({ fill: 'blue', shape: 'dot', text: 'dashboard opened, reading' })
return [{ topic: 'force' },
        { payload: { lv: 'info', m: 'Dashboard opened' + page + ': reading the heater now' } }]

// --- context helpers: use the file store when settings.js provides one, ---
// --- otherwise fall back to memory without throwing.                    ---
function put (k, v) { try { flow.set(k, v, 'file') } catch (e) { flow.set(k, v) } }
function get (k, d) {
  let v; try { v = flow.get(k, 'file') } catch (e) { v = undefined }
  if (v === undefined) v = flow.get(k)
  return v === undefined ? d : v
}

// The get node returns either {topics:{T:{parameters:{P:{value}}}}} or a
// flattened {T:{P:value}}. Accept both rather than assume one shape.
const raw = msg.payload
function val (topic, param) {
  if (!raw || typeof raw !== 'object') return null
  const t = (raw.topics && raw.topics[topic]) || raw[topic]
  if (!t) return null
  const p = (t.parameters && t.parameters[param]) !== undefined
    ? t.parameters[param] : t[param]
  if (p === undefined || p === null) return null
  const v = (typeof p === 'object') ? p.value : p
  return (v === undefined || v === null) ? null : Number(v)
}
function topicOf (name) {
  return (raw && ((raw.topics && raw.topics[name]) || raw[name])) || null
}
function switches () {
  const t = topicOf('Switches'); const out = {}
  if (!t) return out
  const src = t.parameters || t
  for (const k of Object.keys(src)) {
    const p = src[k]
    const v = (typeof p === 'object') ? p.value : p
    if (v === 0 || v === 1) out[k] = Number(v)
  }
  return out
}

const prev = get('state', {})
const now = Date.now()

// Energy source: only trust it once the topic has actually been located.
// Energy is two parameters; the UI shows one of five combinations.
const eD = val('EnergySrc', 'DieselLevel')
const eE = val('EnergySrc', 'ElectricLevel')
function energyMode (d, e) {
  if (d == null || e == null) return null
  if (d === 1 && e === 0) return 5
  if (d === 0 && e === 1) return 3
  if (d === 0 && e === 2) return 4
  if (d === 1 && e === 1) return 1
  if (d === 1 && e === 2) return 2
  return null
}
const energyVal = energyMode(eD, eE)

const st = {
  ts: now,
  online: true,
  lastOk: now,
  room: {
    mode:    val('RoomClimate', 'Mode'),
    tgt:     val('AirHeating', 'TgtTemp'),
    temp:    val('RoomClimate', 'Temp') !== null
               ? val('RoomClimate', 'Temp') : val('AirHeating', 'Temp'),
    airMode: val('AirHeating', 'Mode'),
    active: val('RoomClimate', 'Active'),
    fanLevel: val('AirCirculation', 'FanLevel')
  },
  water: {
    mode: val('WaterHeating', 'Mode'),
    temp: val('WaterHeating', 'Temp'),
    active: val('WaterHeating', 'Active'),
    boost: val('WaterHeating', 'FasterHeatingMode')
  },
  energy: {
    mode: energyVal, diesel: eD, electric: eE,
    label: energyVal === null ? 'Not available'
      : ({ 1: 'Diesel + electric 900 W', 2: 'Diesel + electric 1800 W',
           3: 'Electric 900 W', 4: 'Electric 1800 W', 5: 'Diesel'
         }[energyVal] || String(energyVal))
  },
  switches: switches(),
  // A control is offered when the heater actually reports that parameter.
  caps: {
    energy:   eD !== null && eE !== null,
    fanLevel: val('AirCirculation', 'FanLevel') !== null,
    boost:    val('WaterHeating', 'FasterHeatingMode') !== null,
    waterOff: val('WaterHeating', 'Active') !== null
  },
  site: prev.site || { soc: null, acIn: null },
  guard: prev.guard || { reason: '' },
  errors: [],
  pending: prev.pending || {}
}

// ---- resolve optimistic UI ------------------------------------------------
// A pending entry is cleared when the device confirms it, or rolled back
// after the window expires so a stuck button never lies to the user.
const WINDOW = 45000
const toasts = []
for (const key of Object.keys(st.pending)) {
  const p = st.pending[key]
  const cur = key === 'room.mode'    ? st.room.mode
            : key === 'room.tgt'     ? st.room.tgt
            : key === 'room.airMode' ? st.room.airMode
            : key === 'water.mode'   ? (st.water.active === 0 ? -1 : st.water.mode)
            : key === 'vent.level'   ? st.room.fanLevel
            : key === 'water.boost'  ? st.water.boost
            : key === 'energy.mode'  ? st.energy.mode
            : key.startsWith('switch.') ? st.switches[key.slice(7)]
            : undefined
  if (cur === p.value) { delete st.pending[key]; continue }
  if (now - p.ts > WINDOW) {
    delete st.pending[key]
    toasts.push({ payload: 'The heater did not accept that change. Showing its actual setting.',
                  color: '#FF9E00' })
  }
}

flow.set('pollBusy', false)
const conn = get('conn', {})
conn.fails = 0
conn.backoffUntil = 0
conn.breaker = 'closed'
conn.lastOk = now
const started = flow.get('pollStartedAt') || now
conn.latency = (conn.latency || []).concat(now - started).slice(-30)
put('conn', conn)
put('state', st)

node.status({ fill: 'green', shape: 'dot',
              text: (st.room.temp == null ? '--' : (st.room.temp / 10).toFixed(1)) + 'C' })

const out = [{ payload: st }, { payload: raw }, null,
             { payload: { lv: 'info', m: 'Read ok in ' + (now - started) + ' ms' } }]
if (toasts.length) out[2] = toasts[0]
return out

// --- context helpers: use the file store when settings.js provides one, ---
// --- otherwise fall back to memory without throwing.                    ---
function put (k, v) { try { flow.set(k, v, 'file') } catch (e) { flow.set(k, v) } }
function get (k, d) {
  let v; try { v = flow.get(k, 'file') } catch (e) { v = undefined }
  if (v === undefined) v = flow.get(k)
  return v === undefined ? d : v
}

// Exponential backoff with a circuit breaker. Five consecutive failures
// opens the breaker and slows polling right down until one read succeeds.
const now = Date.now()
flow.set('pollBusy', false)
const conn = get('conn', { fails: 0, reconnects: 0, latency: [] })
conn.fails = (conn.fails || 0) + 1
conn.reconnects = (conn.reconnects || 0) + 1
const step = Math.min(conn.fails, 6)
const wait = Math.min(30000 * Math.pow(2, step - 1), 900000)  // 30s .. 15min
conn.backoffUntil = now + wait
conn.breaker = conn.fails >= 5 ? 'open' : 'closed'
put('conn', conn)

const st = get('state', {})
st.online = false
st.ts = now
put('state', st)

node.status({ fill: 'red', shape: 'ring', text: 'fail ' + conn.fails })

const out = [{ payload: st }, { payload: {
  lv: conn.fails >= 5 ? 'error' : 'warn',
  m: 'Read failed (' + conn.fails + '): ' + (msg.error && msg.error.message || 'unknown')
     + ' — retrying in ' + Math.round(wait / 1000) + 's'
} }, null]
if (conn.fails === 5) {
  out[2] = { payload: 'Lost contact with the heater. Check the panel and Bluetooth.',
             color: '#F44336' }
}
return out

// --- context helpers: use the file store when settings.js provides one, ---
// --- otherwise fall back to memory without throwing.                    ---
function put (k, v) { try { flow.set(k, v, 'file') } catch (e) { flow.set(k, v) } }
function get (k, d) {
  let v; try { v = flow.get(k, 'file') } catch (e) { v = undefined }
  if (v === undefined) v = flow.get(k)
  return v === undefined ? d : v
}

// =====================================================================
//  COMMAND MAP -- the only place a UI key becomes a Truma write.
//  Topics verified by this project against the live D6E (August tests)
//  and truma-guiv2/README.md, not just the package docs.
// =====================================================================
const MAP = {
  'room.mode':    { tn: 'RoomClimate',    pn: 'Mode'              }, // 0 off / 3 heat / 5 vent
  'room.tgt':     { tn: 'AirHeating',     pn: 'TgtTemp'           }, // tenths of a degree
  'room.airMode': { tn: 'AirHeating',     pn: 'Mode'              }, // 0 fast / 1 comfort
  'water.mode':   { tn: 'WaterHeating',   pn: 'Mode'              }, // 0=40C 1=60C 2=70C
  'water.active': { tn: 'WaterHeating',   pn: 'Active'            }, // 0 off / 1 on
  'water.boost':  { tn: 'WaterHeating',   pn: 'FasterHeatingMode' }, // 0 / 1
  'vent.level':   { tn: 'AirCirculation', pn: 'FanLevel'          }, // 0..10
  'energy.diesel':   { tn: 'EnergySrc',   pn: 'DieselLevel'       }, // 0 / 1
  'energy.electric': { tn: 'EnergySrc',   pn: 'ElectricLevel'     }  // 0 / 1 / 2
}

// energy.mode is a UI-level key only. It never reaches the heater directly:
// cmd_router expands it into an ordered pair of the two writes above.
const ENERGY = {
  5: { d: 1, e: 0, l: 'Diesel' },
  3: { d: 0, e: 1, l: 'Electric 900 W' },
  4: { d: 0, e: 2, l: 'Electric 1800 W' },
  1: { d: 1, e: 1, l: 'Diesel + electric 900 W' },
  2: { d: 1, e: 2, l: 'Diesel + electric 1800 W' }
}

// Ordering rule. Never draw more power than max(start, target) on the way,
// and never pass through an unintended hybrid state.
//   electric going down  -> drop electric first
//   diesel changing      -> then diesel
//   electric going up    -> raise electric last
function energySteps (from, to) {
  const steps = []
  if (to.e < from.e) steps.push({ key: 'energy.electric', value: to.e })
  if (to.d !== from.d) steps.push({ key: 'energy.diesel', value: to.d })
  if (to.e > from.e) steps.push({ key: 'energy.electric', value: to.e })
  return steps
}

// Expand scenes, validate, guard, then hand a concrete write to the queue.
const RANGE = {
  'room.mode':       v => [0, 3, 5].includes(v),
  'room.tgt':        v => v >= 50 && v <= 300,
  'room.airMode':    v => [0, 1].includes(v),
  'water.mode':      v => [0, 1, 2].includes(v),
  'water.active':    v => [0, 1].includes(v),
  'water.boost':     v => [0, 1].includes(v),
  'vent.level':      v => v >= 0 && v <= 10,
  'energy.diesel':   v => [0, 1].includes(v),
  'energy.electric': v => [0, 1, 2].includes(v)
}

const p = msg.payload || {}
if (p.source === 'dashboard' || String(p.source || '').startsWith('scene')) {
  put('lastUserAction', Date.now())
}
const st0 = flow.get('liveState') || get('state', {})
let list = []
let txn = null          // set when several writes must land in a fixed order

if (p.key === 'energy.mode') {
  // ---- energy is two parameters, written in a safe order ----
  const to = ENERGY[Number(p.value)]
  if (!to) return [null, { payload: { lv: 'warn', m: 'Unknown energy mode ' + p.value } }, null]
  const cur = st0.energy || {}
  const from = { d: cur.diesel == null ? 0 : cur.diesel,
                 e: cur.electric == null ? 0 : cur.electric }
  const steps = energySteps(from, to)
  if (!steps.length) return [null, null, null]     // already there
  txn = 'energy:' + Math.random().toString(36).slice(2, 8)
  list = steps.map(x => Object.assign({ source: p.source, txn, uiKey: 'energy.mode',
                                        uiValue: Number(p.value) }, x))
} else if (p.key === 'water.mode' && Number(p.value) >= 0) {
  // ---- turning the boiler on: pick the temperature, then activate ----
  txn = 'water:' + Math.random().toString(36).slice(2, 8)
  list = [
    { key: 'water.mode', value: Number(p.value), source: p.source, txn,
      uiKey: 'water.mode', uiValue: Number(p.value) },
    { key: 'water.active', value: 1, source: p.source, txn, minGap: 2000,
      uiKey: 'water.mode', uiValue: Number(p.value) }
  ]
} else if (p.key === 'water.off') {
  list = [{ key: 'water.active', value: 0, source: p.source,
            uiKey: 'water.mode', uiValue: -1 }]
} else if (p.key === 'vent.on') {
  txn = 'vent:' + Math.random().toString(36).slice(2, 8)
  list = [
    { key: 'room.mode', value: 5, source: p.source, txn, uiKey: 'room.mode', uiValue: 5 },
    { key: 'vent.level', value: Number(p.value), source: p.source, txn,
      uiKey: 'vent.level', uiValue: Number(p.value) }
  ]
} else {
  list = [p]
}

const st = st0
const out = []
const logs = []
let toast = null

for (const c of list) {
  const key = c.key
  let value = Number(c.value)

  const m = MAP[key] || (key.startsWith('switch.')
    ? { tn: 'Switches', pn: key.slice(7) } : null)

  if (!m) { logs.push({ lv: 'warn', m: 'unmapped key ' + key }); continue }
  if (RANGE[key] && !RANGE[key](value)) {
    logs.push({ lv: 'warn', m: key + ' value out of range: ' + value }); continue
  }

  // ---- battery guard, off by default (enable on the Failsafe tab) ----
  if (key === 'energy.electric' && value > 0 && get('batteryGuard', false)) {
    const site = st.site || {}
    if (site.acIn === false && site.soc !== null && site.soc < get('batteryGuardSoc', 35)) {
      toast = { payload: 'Electric heating is blocked: no shore power and the battery is at '
                         + Math.round(site.soc) + '%.', color: '#FF9E00' }
      logs.push({ lv: 'warn', m: 'electric blocked by battery guard' })
      continue
    }
  }

  out.push({
    payload: { key, value, tn: m.tn, pn: m.pn },
    topic: 'enqueue',
    cmd: { key, value, tn: m.tn, pn: m.pn, ts: Date.now(),
           token: Math.random().toString(36).slice(2, 10),
           txn: c.txn || null, minGap: c.minGap || 0, seq: out.length,
           uiKey: c.uiKey || key, uiValue: c.uiValue === undefined ? value : c.uiValue,
           source: c.source || p.source || 'unknown' }
  })
  logs.push({ lv: 'cmd', m: 'queue ' + key + ' = ' + value + ' (' + (c.source || p.source || '?') + ')' })
}

node.status({ fill: 'blue', shape: 'dot', text: out.length + ' queued' })
return [out.length ? out : null, logs.length ? logs.map(l => ({ payload: l })) : null,
        toast]

// --- context helpers: use the file store when settings.js provides one, ---
// --- otherwise fall back to memory without throwing.                    ---
function put (k, v) { try { flow.set(k, v, 'file') } catch (e) { flow.set(k, v) } }
function get (k, d) {
  let v; try { v = flow.get(k, 'file') } catch (e) { v = undefined }
  if (v === undefined) v = flow.get(k)
  return v === undefined ? d : v
}

// One BLE write at a time. Repeated writes to the same key collapse into
// the newest value, so dragging a slider never floods the link.
const q = flow.get('cmdQueue') || []
let busy = flow.get('cmdBusy') || false

if (msg.topic === 'release') {
  busy = false
} else if (msg.topic === 'flush') {
  flow.set('cmdQueue', []); flow.set('cmdBusy', false); flow.set('cmdInflight', null)
  node.status({ fill: 'grey', shape: 'ring', text: 'flushed' })
  return null
} else if (msg.cmd) {
  // Transaction steps keep their order and are never merged. Plain commands
  // still coalesce, so dragging a slider cannot flood the link.
  if (msg.cmd.txn) {
    q.push(msg.cmd)
  } else {
    const i = q.findIndex(c => c.key === msg.cmd.key && !c.txn)
    if (i >= 0) q[i] = msg.cmd; else q.push(msg.cmd)
  }
}

if (busy || !q.length) {
  flow.set('cmdQueue', q); flow.set('cmdBusy', busy)
  node.status({ fill: busy ? 'blue' : 'grey', shape: busy ? 'dot' : 'ring',
                text: (busy ? 'writing, ' : '') + q.length + ' waiting' })
  return null
}

// A step with minGap must not start until that long after the previous
// write was confirmed. Hold the queue rather than reorder it.
const cmd = q[0]
const since = Date.now() - (flow.get('lastWriteAt') || 0)
if (cmd.minGap && since < cmd.minGap) {
  flow.set('cmdQueue', q); flow.set('cmdBusy', false)
  node.status({ fill: 'yellow', shape: 'ring',
                text: 'waiting ' + Math.ceil((cmd.minGap - since) / 1000) + 's' })
  return [null, null, { delay: cmd.minGap - since, payload: { topic: 'release' } }]
}
q.shift()
cmd.startedAt = Date.now()
flow.set('cmdQueue', q)
flow.set('cmdBusy', true)
flow.set('cmdInflight', cmd)

// Optimistic: show the intended end state at once. For a transaction the
// pending entry hangs on the UI key, so a two-step write never half-rolls back.
const st = get('state', {})
st.pending = st.pending || {}
st.pending[cmd.uiKey || cmd.key] = {
  value: cmd.uiValue === undefined ? cmd.value : cmd.uiValue,
  token: cmd.token, txn: cmd.txn || null, ts: Date.now()
}
put('state', st)

node.status({ fill: 'blue', shape: 'dot', text: cmd.key })
return [
  { payload: { topic: cmd.tn, parameter: cmd.pn, value: cmd.value }, cmd },
  { payload: st },
  null
]

// --- context helpers: use the file store when settings.js provides one, ---
// --- otherwise fall back to memory without throwing.                    ---
function put (k, v) { try { flow.set(k, v, 'file') } catch (e) { flow.set(k, v) } }
function get (k, d) {
  let v; try { v = flow.get(k, 'file') } catch (e) { v = undefined }
  if (v === undefined) v = flow.get(k)
  return v === undefined ? d : v
}

const cmd = flow.get('cmdInflight') || msg.cmd || {}
const took = cmd.startedAt ? Date.now() - cmd.startedAt : null
flow.set('cmdInflight', null)
flow.set('lastWriteAt', Date.now())

// Only read back once the whole transaction has drained, and read just the
// topics we touched instead of the entire tree.
const q = flow.get('cmdQueue') || []
const more = cmd.txn && q.some(c => c.txn === cmd.txn)
node.status({ fill: 'green', shape: 'dot', text: cmd.key + ' ok' })
return [
  { topic: 'release' },
  { payload: { lv: 'cmd', m: 'wrote ' + cmd.tn + '.' + cmd.pn + ' = ' + cmd.value
      + (took !== null ? ' in ' + took + ' ms' : '') } },
  more ? null : { topic: 'force', payload: [cmd.tn] }
]

// --- context helpers: use the file store when settings.js provides one, ---
// --- otherwise fall back to memory without throwing.                    ---
function put (k, v) { try { flow.set(k, v, 'file') } catch (e) { flow.set(k, v) } }
function get (k, d) {
  let v; try { v = flow.get(k, 'file') } catch (e) { v = undefined }
  if (v === undefined) v = flow.get(k)
  return v === undefined ? d : v
}

const cmd = flow.get('cmdInflight') || {}
flow.set('cmdInflight', null)

// A half-applied transaction is worse than none, so abandon the rest of it.
if (cmd.txn) {
  flow.set('cmdQueue', (flow.get('cmdQueue') || []).filter(c => c.txn !== cmd.txn))
}
const st = get('state', {})
const pk = cmd.uiKey || cmd.key
if (st.pending && pk) { delete st.pending[pk]; put('state', st) }
node.status({ fill: 'red', shape: 'ring', text: (cmd.key || '?') + ' failed' })
return [
  { topic: 'release' },
  { payload: { lv: 'error', m: 'write ' + (cmd.key || '?') + ' failed: '
      + (msg.error && msg.error.message || 'unknown') } },
  { payload: cmd.txn
      ? 'That change did not reach the heater and was rolled back part-way. Check Diagnostics.'
      : 'That change did not reach the heater. Nothing was altered.', color: '#F44336' },
  { payload: st }
]

// --- context helpers: use the file store when settings.js provides one, ---
// --- otherwise fall back to memory without throwing.                    ---
function put (k, v) { try { flow.set(k, v, 'file') } catch (e) { flow.set(k, v) } }
function get (k, d) {
  let v; try { v = flow.get(k, 'file') } catch (e) { v = undefined }
  if (v === undefined) v = flow.get(k)
  return v === undefined ? d : v
}

// Belt and braces: if a write neither returns nor errors, free the queue
// after 60s so the dashboard does not lock up.
const cmd = flow.get('cmdInflight')
if (!flow.get('cmdBusy') || !cmd) return null
if (Date.now() - (cmd.startedAt || 0) < 60000) return null
flow.set('cmdInflight', null)
const st = get('state', {})
if (st.pending) { delete st.pending[cmd.uiKey || cmd.key]; put('state', st) }
if (cmd.txn) flow.set('cmdQueue', (flow.get('cmdQueue') || []).filter(c => c.txn !== cmd.txn))
