// Three independent guards. Each one may emit a command; none of them
// argue with a change the user made in the last ten minutes.
const st = flow.get('liveState') || get('state', {})
const now = Date.now()
// Battery guard ships OFF. Turn it on with:
//   flow.set('batteryGuard', true, 'file')
const cfg = get('failCfg', {
  frostEnabled: true, frostBelow: 60, frostTarget: 100,   // tenths of a degree
  batterySoc: get('batteryGuardSoc', 35),
  staleAfter: 300000, respectUserFor: 600000
})
const batteryGuard = get('batteryGuard', false)
const lastUser = get('lastUserAction', 0)
const cmds = []; const logs = []; let toast = null
const guard = { reason: '' }

// ---------------- 1. stale data ----------------
if (st.lastOk && now - st.lastOk > cfg.staleAfter && st.online !== false) {
  st.online = false
  logs.push({ lv: 'warn', m: 'No fresh data for '
    + Math.round((now - st.lastOk) / 1000) + 's — marking the link down' })
}

// ---------------- 2. frost protection ----------------
const temp = st.room && st.room.temp
if (cfg.frostEnabled && temp != null && temp < cfg.frostBelow) {
  if (st.room.mode === 0) {
    if (now - lastUser > cfg.respectUserFor) {
      cmds.push({ payload: { key: 'room.mode', value: 3, source: 'frost' } })
      cmds.push({ payload: { key: 'room.tgt', value: cfg.frostTarget, source: 'frost' } })
      logs.push({ lv: 'warn', m: 'Frost guard: cabin at ' + (temp / 10).toFixed(1)
        + 'C, turning the heater on' })
      toast = { payload: 'Frost protection turned the heater on. The cabin dropped to '
        + (temp / 10).toFixed(1) + ' degrees.', color: '#FF9E00' }
    } else {
      guard.reason = 'The cabin is near freezing but you switched the heater off recently, so frost protection is holding back.'
    }
  }
}

// ---------------- 3. battery guard ----------------
const site = st.site || {}
if (batteryGuard && site.acIn === false && site.soc != null
    && site.soc < cfg.batterySoc
    && st.energy && st.energy.electric > 0) {
  if (st.caps && st.caps.energy) {
    cmds.push({ payload: { key: 'energy.mode', value: 5, source: 'battery' } })
    logs.push({ lv: 'warn', m: 'Battery at ' + Math.round(site.soc)
      + '% with no shore power — switching to diesel' })
    toast = { payload: 'Switched to diesel. The battery is down to '
      + Math.round(site.soc) + '% and there is no shore power.', color: '#FF9E00' }
  } else {
    guard.reason = 'Battery is low and the heater is on electric, but this build cannot change the energy source yet.'
  }
}

st.guard = guard
put('state', st)
return [cmds.length ? cmds : null,
        logs.length ? logs.map(l => ({ payload: l })) : null,
        toast, { payload: st }]

