// Rules live in one array. The whole schedule can be paused without
// losing anything, which is what you want when you unexpectedly stay a
// night longer.
let rules = get('schedRules', [])
let enabled = get('schedEnabled', true)
const p = msg.payload || {}
let log = null

const ACTIONS = ['room', 'water', 'vent']
const MODES = { room: [3], water: [0, 1, 2], vent: [5] }

switch (msg.topic) {
  case 'add': {
    const action = ACTIONS.includes(p.action) ? p.action : 'room'
    const r = {
      id: 'r' + Date.now().toString(36),
      days: Array.isArray(p.days) && p.days.length ? p.days : [0,1,2,3,4,5,6],
      start: p.start || '07:00',
      end: p.end || '09:00',
      action: action,
      energy: [1,2,3,4,5].includes(Number(p.energy)) ? Number(p.energy) : null,
      tgt: Math.min(300, Math.max(50, Number(p.tgt) || 200)),
      airMode: [0,1].includes(Number(p.airMode)) ? Number(p.airMode) : 1,
      wmode: [0,1,2].includes(Number(p.wmode)) ? Number(p.wmode) : 1,
      boost: p.boost ? 1 : 0,
      fanLevel: Math.min(10, Math.max(0, Number(p.fanLevel) || 5)),
      on: p.on !== false
    }
    rules.push(r)
    log = { lv: 'info', m: 'Added ' + action + ' timer ' + r.start + '-' + r.end }
    break
  }
  case 'delete':
    rules = rules.filter(r => r.id !== p.id)
    log = { lv: 'info', m: 'Deleted a timer' }
    break
  case 'toggle':
    rules = rules.map(r => r.id === p.id ? Object.assign({}, r, { on: !!p.on }) : r)
    break
  case 'enable':
    enabled = !!p.enabled
    log = { lv: 'info', m: 'Schedule ' + (enabled ? 'resumed' : 'paused') }
    break
  case 'disableRule': {
    // Called when the user overrides a running timer by hand.
    rules = rules.map(r => r.id === p.id ? Object.assign({}, r, { on: false }) : r)
    log = { lv: 'warn', m: 'Timer switched off after a manual change' }
    break
  }
}

rules.sort((a, b) => a.start.localeCompare(b.start))
put('schedRules', rules)
put('schedEnabled', enabled)
node.status({ fill: enabled ? 'green' : 'grey', shape: 'dot',
              text: rules.length + ' rules' })
// An edit (add, delete, on/off, pause/resume, manual override) is handed to
// Evaluate rules at once instead of waiting for its next minute tick, so a
// timer that was just removed or switched off ends right now and the
// overview on the Schedule page is refreshed from the recomputed state.
// Evaluate rules publishes that overview itself; only a plain 'list'
// (publish on start) is answered from here.
const edited = ['add', 'delete', 'toggle', 'enable', 'disableRule'].includes(msg.topic)
const active = get('schedActive', null)
return [edited ? null : { payload: { rules: rules, enabled: enabled, active: active } },
        log ? { payload: log } : null,
        edited ? { topic: 'edit' } : null]

