  if (snap.wactive === 0) push('water.off', 0); else push('water.mode', snap.wmode)
}
if (keep !== 'airMode') push('room.airMode', snap.airMode)
if (keep !== 'fanLevel') push('vent.level', snap.fanLevel)
if (keep !== 'tgt') push('room.tgt', snap.tgt)
if (keep !== 'mode') push('room.mode', snap.mode)

