// Edge triggered. A rule fires once when its window opens and once when
// it closes, so you can still override it by hand afterwards.
// Runs every minute and straight after every edit from Rule store
// (msg.topic 'edit'). There is deliberately no early exit when the
// schedule is paused or empty: a running timer that is deleted, switched
// off or paused must still be seen to end, or schedActive (and the
// "timer running" notice) would stay behind for good.
const rules = get('schedRules', [])
const enabled = get('schedEnabled', true)
const st = flow.get('liveState') || get('state', {})
const cmds = []; const logs = []
let active = get('schedActive', null)
const byEdit = msg.topic === 'edit'

const now = new Date()
const day = now.getDay()
const mins = now.getHours() * 60 + now.getMinutes()
const toMin = s => { const [h, m] = String(s).split(':').map(Number); return h * 60 + m }
const inWindow = r => {
  const a = toMin(r.start), b = toMin(r.end)
  return a <= b ? (mins >= a && mins < b) : (mins >= a || mins < b)
}

// Everything a timer can touch, so it can all be put back afterwards.
function snapshot () {
  return {
    mode: st.room ? st.room.mode : null,
    tgt: st.room ? st.room.tgt : null,
    airMode: st.room ? st.room.airMode : null,
    fanLevel: st.room ? st.room.fanLevel : null,
    energy: st.energy ? st.energy.mode : null,
    wmode: st.water ? st.water.mode : null,
    wactive: st.water ? st.water.active : null,
    boost: st.water ? st.water.boost : null
  }
}
function restore (snap) {
  const out = []
  if (!snap) return out
  if (snap.energy != null) out.push({ key: 'energy.mode', value: snap.energy })
  if (snap.boost != null) out.push({ key: 'water.boost', value: snap.boost })
  if (snap.wactive === 0) out.push({ key: 'water.off', value: 0 })
  else if (snap.wmode != null) out.push({ key: 'water.mode', value: snap.wmode })
  if (snap.airMode != null) out.push({ key: 'room.airMode', value: snap.airMode })
  if (snap.fanLevel != null) out.push({ key: 'vent.level', value: snap.fanLevel })
  if (snap.tgt != null) out.push({ key: 'room.tgt', value: snap.tgt })
  // mode last: it decides off / heat / ventilate, including "it was off"
  if (snap.mode != null) out.push({ key: 'room.mode', value: snap.mode })
  return out
}
function apply (r) {
  const out = []
  if (r.energy != null) out.push({ key: 'energy.mode', value: r.energy })
  if (r.action === 'room') {
    out.push({ key: 'room.airMode', value: r.airMode })
    out.push({ key: 'room.tgt', value: r.tgt })
    out.push({ key: 'room.mode', value: 3 })
  } else if (r.action === 'water') {
    out.push({ key: 'water.mode', value: r.wmode })
    if (r.boost) out.push({ key: 'water.boost', value: 1 })
  } else if (r.action === 'vent') {
    out.push({ key: 'vent.on', value: r.fanLevel })
  }
  return out
}

// A paused schedule has nothing running, whatever the clock says. A rule
// that was deleted or switched off simply is not in this list any more,
// so the branches below treat all three the same as a window closing.
const running = enabled
  ? rules.filter(r => r.on && Array.isArray(r.days) && r.days.includes(day) && inWindow(r))
  : []
const wasRunning = active ? active.ids : []
const nowIds = running.map(r => r.id)

// ---- first timer of a stretch: remember where we came from ----
if (nowIds.length && !wasRunning.length) {
  active = { ids: nowIds, snap: snapshot(), since: Date.now(),
             until: running.map(r => r.end).sort().slice(-1)[0] }
  put('schedActive', active)
  for (const r of running) for (const c of apply(r))
    cmds.push({ payload: Object.assign({ source: 'schedule' }, c) })
  logs.push({ lv: 'info', m: 'Timer started, previous settings saved' })
}
// ---- a further timer joins: apply it, keep the original snapshot ----
else if (nowIds.length && wasRunning.length) {
  const fresh = running.filter(r => wasRunning.indexOf(r.id) < 0)
  for (const r of fresh) for (const c of apply(r))
    cmds.push({ payload: Object.assign({ source: 'schedule' }, c) })
  if (fresh.length) logs.push({ lv: 'info', m: 'A second timer started' })
  active.ids = nowIds
  active.until = running.map(r => r.end).sort().slice(-1)[0]
  put('schedActive', active)
}
// ---- last one ended: put everything back, including "it was off" ----
else if (!nowIds.length && wasRunning.length) {
  for (const c of restore(active && active.snap))
    cmds.push({ payload: Object.assign({ source: 'schedule' }, c) })
  put('schedActive', null)
  active = null
  logs.push({ lv: 'info', m: byEdit
    ? 'Timer removed, switched off or paused: previous settings restored'
    : 'Timer ended, previous settings restored' })
}

// ---- when does the next timer start? -------------------------------------
// Worked out here, where the clock and the rules live, so the Schedule
// page only has to show it. Looks up to a week ahead over the timers that
// are switched on; null when none is. 'in' is minutes from now.
function nextStart () {
  const DAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday']
  let best = null
  for (const r of rules) {
    if (!r.on || !Array.isArray(r.days) || !r.days.length) continue
    const a = toMin(r.start)
    for (let off = 0; off < 8; off++) {
      const d = (day + off) % 7
      if (!r.days.includes(d)) continue
      if (off === 0 && a <= mins) continue          // already started today
      const inMin = off * 1440 + a - mins
      if (!best || inMin < best.in) {
        best = { id: r.id, day: d, start: r.start, in: inMin,
                 at: Date.now() + inMin * 60000,
                 label: (off === 0 ? 'today' : off === 1 ? 'tomorrow' : DAYS[d]) + ' at ' + r.start }
      }
      break
    }
  }
  return best
}
const next = nextStart()

node.status(!enabled ? { fill: 'grey', shape: 'ring', text: 'paused' }
  : active ? { fill: 'blue', shape: 'dot', text: 'running until ' + active.until }
  : next ? { fill: 'green', shape: 'dot', text: rules.length + ' armed, next ' + next.label }
  : { fill: 'green', shape: 'dot', text: rules.length + ' armed' })
return [cmds.length ? cmds : null,
        logs.length ? logs.map(l => ({ payload: l })) : null,
        { payload: { active: active, rules: rules, enabled: enabled, next: next } }]

