// 48 hours at one sample a minute is 2880 points; we thin to one every
// two minutes to keep the chart responsive on a phone.
const st = msg.payload || {}
if (!st.online || !st.room) return null
const now = Date.now()
const buf = get('histBuf', [])
const last = buf[buf.length - 1]
if (last && now - last.t < 120000) return null

buf.push({ t: now, r: st.room.temp, s: st.room.tgt,
           w: st.water.temp, m: st.room.mode })
while (buf.length && now - buf[0].t > 48 * 3600 * 1000) buf.shift()
put('histBuf', buf)

const series = [
  { topic: 'Cabin',   payload: st.room.temp  == null ? null : st.room.temp / 10,  timestamp: now },
  { topic: 'Setpoint',payload: st.room.tgt   == null ? null : st.room.tgt / 10,   timestamp: now },
  { topic: 'Boiler',  payload: st.water.temp == null ? null : st.water.temp / 10, timestamp: now }
].filter(s => s.payload !== null)

// ---- daily statistics -------------------------------------------------
const dayAgo = now - 86400000
const day = buf.filter(b => b.t >= dayAgo && b.r != null)
let stats = { min:'--', max:'--', avg:'--', minAt:'--', maxAt:'--', run:'--', n: buf.length }
if (day.length) {
  let lo = day[0], hi = day[0], sum = 0, run = 0
  for (const b of day) {
    if (b.r < lo.r) lo = b
    if (b.r > hi.r) hi = b
    sum += b.r
    if (b.m === 3) run += 2                       // 2 minutes per sample
  }
  const hhmm = t => new Date(t).toLocaleTimeString([], { hour:'2-digit', minute:'2-digit' })
  stats = {
    min: (lo.r/10).toFixed(1), minAt: hhmm(lo.t),
    max: (hi.r/10).toFixed(1), maxAt: hhmm(hi.t),
    avg: (sum/day.length/10).toFixed(1),
    run: Math.floor(run/60) + 'h ' + (run%60) + 'm',
    n: buf.length
  }
}
return [series, { payload: stats }]

