const conn = get('conn', {})
const st = get('state', {})
const q = flow.get('cmdQueue') || []
const lat = (conn.latency || []).slice().sort((a, b) => a - b)
const med = lat.length ? lat[Math.floor(lat.length / 2)] : null
const now = Date.now()
const ago = t => !t ? 'never'
  : (now - t) < 60000 ? Math.round((now - t) / 1000) + 's ago'
  : Math.round((now - t) / 60000) + 'm ago'
return { payload: {
