const a = (msg.payload || {}).action
const out = [null, null, null, null]
switch (a) {
  case 'poll':
    out[0] = { topic: 'force' }
    out[2] = { payload: { lv: 'info', m: 'Manual read requested' } }
    break
  case 'reconnect': {
    const conn = get('conn', {})
    conn.fails = 0; conn.backoffUntil = 0; conn.breaker = 'closed'
    put('conn', conn)
    put('bleReleaseUntil', 0); global.set('bleReleaseUntil', 0)
    out[0] = { topic: 'force' }
    out[2] = { payload: { lv: 'info', m: 'Connection reset by hand' } }
    out[3] = { payload: 'Reconnecting to the heater.', color: '#4790D3' }
    break
  }
  case 'rediscover':
    flow.set('rediscover', true)
    out[0] = { topic: 'force' }
    out[2] = { payload: { lv: 'info', m: 'Full tree read requested — check Raw device data' } }
    out[3] = { payload: 'Reading the full device tree. Open Raw device data below.',
               color: '#4790D3' }
    break
  case 'flush':
    out[1] = { topic: 'flush' }
    out[2] = { payload: { lv: 'info', m: 'Command queue cleared' } }
    break
  case 'release':
    put('bleReleaseUntil', Date.now() + 300000); global.set('bleReleaseUntil', Date.now() + 300000)
    out[2] = { payload: { lv: 'info', m: 'Bluetooth released for 5 minutes' } }
    out[3] = { payload: 'Bluetooth is free for five minutes. Pair with the Truma app now.',
               color: '#4790D3' }
    break
}
return out

// Venus stops publishing N/ topics 60 seconds after the last keepalive.
// An empty payload asks Venus to republish EVERY topic; only the first one
// needs that. Later ones suppress the republish, which keeps the CPU and
// this tab's "GX Touch writes" subscription quiet.
const id = global.get('venusPortalId')
if (!id) { node.status({ fill:'yellow', shape:'ring', text:'no portal id yet' }); return null }
const first = !flow.get('keepaliveSent')
flow.set('keepaliveSent', true)
node.status({ fill: 'green', shape: 'dot', text: first ? 'alive (full publish)' : 'alive' })
return { topic: 'R/' + id + '/keepalive',
         payload: first ? '' : JSON.stringify({ 'keepalive-options': ['suppress-republish'] }) }

// --- context helpers: use the file store when settings.js provides one, ---
// --- otherwise fall back to memory without throwing.                    ---
function put (k, v) { try { flow.set(k, v, 'file') } catch (e) { flow.set(k, v) } }
function get (k, d) {
  let v; try { v = flow.get(k, 'file') } catch (e) { v = undefined }
  if (v === undefined) v = flow.get(k)
  return v === undefined ? d : v
}

const v = msg.payload && msg.payload.value
const st = get('state', {})
st.site = st.site || { soc: null, acIn: null }
if (String(msg.topic).endsWith('/Soc')) st.site.soc = (v == null ? null : Number(v))
if (String(msg.topic).endsWith('/Connected')) st.site.acIn = (v == null ? null : Number(v) === 1)
put('state', st)
node.status({ text: (st.site.soc == null ? '--' : Math.round(st.site.soc) + '%')
  + ' / ' + (st.site.acIn ? 'AC in' : 'no AC') })
return { payload: st }

// --- context helpers: use the file store when settings.js provides one, ---
// --- otherwise fall back to memory without throwing.                    ---
function put (k, v) { try { flow.set(k, v, 'file') } catch (e) { flow.set(k, v) } }
function get (k, d) {
  let v; try { v = flow.get(k, 'file') } catch (e) { v = undefined }
  if (v === undefined) v = flow.get(k)
  return v === undefined ? d : v
}
// Three jobs, in this order:
//  1. keep the bridge's own copy of the latest state (flow context is per
//     tab, so the Poller's `state` is NOT visible here — see INTERFACE.md §5)
//  2. retained truma/state for any other consumer on the boat
//  3. W/<portal>/settings/0/Settings/Truma/<Leaf> — the Venus settings tree
//     the GX Touch page binds to. The leaves are created at flow start by
//     "Ensure Truma settings" on this tab; a W/ write to a missing path is
//     silently dropped by Venus.
const st = msg.payload
if (!st || typeof st !== 'object') return null
const now = Date.now()

// A message from the Poller carries the full tree (st.room). A message from
// the command queue carries the optimistic view (st.pending) and may be
// partial. Keep both, merge on use.
if (st.room) put('bridgeFull', st)
put('bridgePending', st.pending || {})
const full = st.room ? st : get('bridgeFull', null)
if (!full) return null

const id = global.get('venusPortalId')
const out = [{ topic: 'truma/state', payload: full, retain: true }]
if (!id) { node.status({ fill: 'yellow', shape: 'ring', text: 'no portal id yet' }); return [out] }

const base = 'W/' + id + '/settings/0/Settings/Truma/'
const write = (p, v) => {
  if (v === null || v === undefined || Number.isNaN(v)) return
  out.push({ topic: base + p, payload: { value: v } })
}

// Optimistic view: while a write is in flight the Touch must show the
// intended value, exactly like the dashboard does. Otherwise our own mirror
// write bounces the button back to the old value until the read-back
// confirms it (a visible flicker, and a second spurious command if the user
// taps again). Entries older than the dashboard's own 45 s window are stale
// leftovers and are ignored.
const WINDOW = 45000
const pend = get('bridgePending', {})
const live = k => (pend[k] && (now - (pend[k].ts || 0)) <= WINDOW) ? pend[k] : null
const eff = (k, actual) => { const p = live(k); return p ? p.value : actual }
const room = full.room || {}, water = full.water || {}, energy = full.energy || {}
const online = st.online !== undefined ? !!st.online : !!full.online

// Online is written unconditionally so the Touch also learns about link loss.
write('Online', online ? 1 : 0)

if (online) {
  // NOTE ON UNITS. The protocol works in tenths of a degree; the QML page
  // uses whole degrees (int slider 5..30). Convert on the way out here, and
  // back again in "GX Touch to command".
  const tgt = eff('room.tgt', room.tgt)
  write('RoomMode',          eff('room.mode', room.mode))
  write('TargetTemperature', tgt == null ? null : tgt / 10)
  write('AirMode',           eff('room.airMode', room.airMode))
  write('FanLevel',          eff('vent.level', room.fanLevel))

  // The water transaction pends on `water.mode` (value -1 means "off",
  // see cmd_router water.off). WaterMode itself keeps the heater's last mode.
  const pw = live('water.mode')
  const wm = pw ? (pw.value < 0 ? water.mode : pw.value) : water.mode
  const wa = pw ? (pw.value < 0 ? 0 : 1) : eff('water.active', water.active)
  write('WaterMode',   wm)
  write('WaterActive', wa)
  write('Boost',       eff('water.boost', water.boost))
  write('EnergyMode',  eff('energy.mode', energy.mode))

  // Measured temperatures. The two temperature services the QML binds to
  // (com.victronenergy.temperature.trumaroom / trumaboiler) are provided by
  // venus/dbus-truma-temp, which mirrors these two settings paths.
  write('RoomTemperature',   room.temp  == null ? null : room.temp / 10)
  write('BoilerTemperature', water.temp == null ? null : water.temp / 10)
}
node.status({ fill: online ? 'green' : 'red', shape: 'dot',
              text: (out.length - 1) + ' paths' + (Object.keys(pend).length ? ', pending' : '') })
return [out]

// --- context helpers: use the file store when settings.js provides one, ---
// --- otherwise fall back to memory without throwing.                    ---
function put (k, v) { try { flow.set(k, v, 'file') } catch (e) { flow.set(k, v) } }
function get (k, d) {
  let v; try { v = flow.get(k, 'file') } catch (e) { v = undefined }
  if (v === undefined) v = flow.get(k)
  return v === undefined ? d : v
}
// Keeps the two screens in step. Every change of a /Settings/Truma/* value
// on Venus lands here — including the echo of our own mirror writes from
// "Publish to D-Bus mirror". Only a value that disagrees with what the
// heater last reported AND with any write already in flight is a real
// user action on the GX Touch.
//
// State comes from this tab's own cache (bridgeFull / bridgePending, kept by
// publish_state). Flow context is per tab, so the Poller's `state` is not
// visible here; reading it would make `cur` undefined and turn every echo
// into a heater write — an endless BLE loop.
const MAPBACK = {
  RoomMode:          'room.mode',
  TargetTemperature: 'room.tgt',
  AirMode:           'room.airMode',
  WaterMode:         'water.mode',
  WaterActive:       'water.active',
  Boost:             'water.boost',
  EnergyMode:        'energy.mode',
  FanLevel:          'vent.level'
}
const TENTHS = { TargetTemperature: true }   // whole degrees on D-Bus
const leaf = String(msg.topic || '').split('/').pop()
let key = MAPBACK[leaf]
if (!key) return null
let v = msg.payload && msg.payload.value
if (v === null || v === undefined) return null
v = Number(v)
if (Number.isNaN(v)) return null
if (TENTHS[leaf]) v = Math.round(v * 10)
const now = Date.now()

const full = get('bridgeFull', null)
if (!full) {
  // Nothing has been read from the heater yet, so nothing can be compared.
  // Ignore rather than guess; the first poll is 8 s after start.
  return null   // Venus republishes retained values at start; not a user action
}
const room = full.room || {}, water = full.water || {}, energy = full.energy || {}
const cur = key === 'room.mode'    ? room.mode
          : key === 'room.tgt'     ? room.tgt
          : key === 'room.airMode' ? room.airMode
          : key === 'water.mode'   ? water.mode
          : key === 'water.active' ? water.active
          : key === 'water.boost'  ? water.boost
          : key === 'vent.level'   ? room.fanLevel
          : energy.mode
if (cur !== null && cur !== undefined && v === Number(cur)) return null

// The echo of an optimistic value our own mirror just wrote.
const WINDOW = 45000
const pend = get('bridgePending', {})
const pk = key === 'water.active' ? 'water.mode' : key
const p = pend[pk]
if (p && (now - (p.ts || 0)) <= WINDOW) {
  const pv = key === 'water.active' ? (p.value < 0 ? 0 : 1) : Number(p.value)
  if (pv === v) return null
  if (key === 'water.active' && v === 1 && p.value >= 0) return null  // txn already activates
}

// One Touch tap is a burst of 2-3 settings writes. The water buttons write
// WaterMode then WaterActive=1; cmd_router's water.mode transaction already
// activates the boiler 2 s later, so that second write is dropped here.
if (key === 'water.mode') flow.set('gxWaterModeAt', now)
if (key === 'water.active') {
  if (v === 1 && now - (flow.get('gxWaterModeAt') || 0) < 5000) return null
  if (v === 0) key = 'water.off'   // same heater write; the dashboard shows "Off" pending
}

// Belt and braces against any echo loop reaching the heater: more than 12
// Touch commands inside 30 s is not a human. Drop and shout.
const win = (flow.get('gxRate') || []).filter(t => now - t < 30000)
win.push(now); flow.set('gxRate', win)
if (win.length > 12) {
  node.status({ fill: 'red', shape: 'ring', text: 'loop guard' })
  return [null, { payload: { lv: 'error', m: 'GX Touch bridge: ' + win.length
    + ' commands in 30 s, dropping ' + leaf + ' — check for an echo loop' } }]
}

put('lastUserAction', now)
node.status({ fill: 'blue', shape: 'dot', text: leaf + ' = ' + v })
return [{ payload: { key, value: v, source: 'gxtouch' } },
        { payload: { lv: 'cmd', m: 'GX Touch changed ' + leaf + ' to ' + v + ' (' + key + ')' } }]

// Pass-through tap. Output 1 continues the real flow
// untouched; output 2 feeds the debug node only.
const copy = { topic: 'truma/raw', payload: msg.payload }
return [msg, copy]

// Pass-through tap. Output 1 continues the real flow
// untouched; output 2 feeds the debug node only.
const copy = { topic: 'truma/state', payload: msg.payload }
// strip the noisy bits so the sidebar stays readable
if (copy.payload) {
  copy.payload = Object.assign({}, copy.payload)
  delete copy.payload.ts
}
return [msg, copy]

// Pass-through tap. Output 1 continues the real flow
// untouched; output 2 feeds the debug node only.
const copy = { topic: 'truma/command', payload: msg.payload }
const c = msg.cmd || {}
copy.payload = { key: c.key, value: c.value,
                 write: c.tn + '.' + c.pn + ' = ' + c.value,
                 source: c.source, token: c.token }
return [msg, copy]

// Pass-through tap. Output 1 continues the real flow
// untouched; output 2 feeds the debug node only.
const copy = { topic: 'truma/error', payload: msg.payload }
// the log link carries every level; only surface the bad ones
const buf = Array.isArray(msg.payload) ? msg.payload : []
const last = buf[buf.length - 1]
if (!last || (last.lv !== 'error' && last.lv !== 'warn')) return [msg, null]
copy.payload = { level: last.lv, message: last.m,
                 at: new Date(last.ts).toLocaleTimeString() }
return [msg, copy]

// Pass-through tap. Output 1 continues the real flow
// untouched; output 2 feeds the debug node only.
const copy = { topic: 'truma/mqtt', payload: msg.payload }
copy.payload = { topic: msg.topic, value: msg.payload }
return [msg, copy]

// Pass-through tap. Output 1 continues the real flow
// untouched; output 2 feeds the debug node only.
const copy = { topic: 'truma/uncaught', payload: msg.payload }
copy.payload = { node: (msg.error && msg.error.source && msg.error.source.id),
                 message: (msg.error && msg.error.message) }
msg.payload = { lv: 'error', m: 'Uncaught: '
  + ((msg.error && msg.error.message) || 'unknown') }
return [msg, copy]

// Creates the /Settings/Truma/* paths on com.victronenergy.settings with the
// Venus `dbus` CLI and localsettings' AddSetting(group, name, default, type,
// min, max). Re-running it on a path that already exists keeps the current
// value (localsettings only re-affirms type/range). All of these paths are
// custom — stock Venus OS has no Truma service. See dbus-paths.md.
const S = [
  // name               default type min max   (min=max=0 means "no range")
  ['RoomMode',          0,   'i', 0,   5  ],   // 0 off / 3 heat / 5 vent
  ['TargetTemperature', 20.0,'f', 5.0, 30.0], // whole degrees C
  ['AirMode',           1,   'i', 0,   1  ],   // 0 fast / 1 comfort
  ['WaterMode',         0,   'i', 0,   2  ],   // 0=40 1=60 2=70
  ['WaterActive',       0,   'i', 0,   1  ],
  ['Boost',             0,   'i', 0,   1  ],
  ['EnergyMode',        5,   'i', 1,   5  ],
  ['FanLevel',          0,   'i', 0,   10 ],
  ['RoomTemperature',   0.0, 'f', 0,   0  ],   // flow-only, not bound by QML
  ['BoilerTemperature', 0.0, 'f', 0,   0  ],
  ['Online',            0,   'i', 0,   1  ]
]
const fmt = (v, t) => t === 'f' ? Number(v).toFixed(1) : String(v)
const cmds = S.map(([n, d, t, lo, hi]) =>
  'dbus -y com.victronenergy.settings /Settings AddSetting Truma ' + n + ' '
  + fmt(d, t) + ' ' + t + ' ' + fmt(lo, t) + ' ' + fmt(hi, t))
node.status({ fill: 'blue', shape: 'dot', text: 'creating ' + S.length + ' paths' })
// AddSetting prints its return value (0 = ok) but never fails the exit code,
// so read one path back at the end: a number on the last line proves the
// tree exists (checked in "Ensure Truma settings: result").
msg.payload = cmds.join(' ; ') + ' ; dbus -y com.victronenergy.settings /Settings/Truma/FanLevel GetValue'
return msg

// Output of the AddSetting run. The last line is the read-back of
// /Settings/Truma/FanLevel: a number means the tree exists.
const lines = String(msg.payload || '').trim().split('\n').filter(Boolean)
const last = lines.length ? lines[lines.length - 1].trim() : ''
const err = String(msg.stderr || '').trim()
const rc = msg.rc && msg.rc.code
if (rc === 0 && !err && /^-?\d+(\.\d+)?$/.test(last)) {
  node.status({ fill: 'green', shape: 'dot', text: 'settings ok' })
  return { payload: { lv: 'info', m: 'Truma settings paths present on com.victronenergy.settings' } }
}
node.status({ fill: 'red', shape: 'ring', text: 'AddSetting failed' })
return { payload: { lv: 'error', m: 'AddSetting check failed (rc ' + rc + '): '
  + (err || last || 'no output') + ' — run the commands from DEPLOY.md §3 by hand' } }

// --- context helpers: use the file store when settings.js provides one, ---
// --- otherwise fall back to memory without throwing.                    ---
function put (k, v) { try { flow.set(k, v, 'file') } catch (e) { flow.set(k, v) } }
function get (k, d) {
  let v; try { v = flow.get(k, 'file') } catch (e) { v = undefined }
  if (v === undefined) v = flow.get(k)
  return v === undefined ? d : v
}
// Recovery for the case the flow cannot see: the Truma app on a phone took
// the BLE link, the panel was unreachable for a while, and the Poller's
// exponential backoff (30 s .. 15 min) is now holding everything back long
// after the panel is free again. Once every 5 minutes, while reads are
// failing, try a plain BlueZ connect. If it succeeds, drop the backoff and
// read immediately.
//
// Turn off with:  flow.set('bleWatchdog', false, 'file')   (on this tab)
const now = Date.now()
if (get('bleWatchdog', true) === false) return null
const hold = Math.max(get('bleReleaseUntil', 0), global.get('bleReleaseUntil') || 0)
if (hold > now) { node.status({ fill: 'grey', shape: 'ring', text: 'released for pairing' }); return null }

const conn = get('conn', {})
const fails = conn.fails || 0
const lastOk = conn.lastOk || 0
const down = lastOk ? now - lastOk : 0
if (fails < 2 && down < 300000) { node.status({}); return null }
if (now - (flow.get('bleKickAt') || 0) < 300000) return null
flow.set('bleKickAt', now)
// Set TRUMA_MAC once (and TRUMA_BLE_ADAPTER when a USB adapter is used):
// either in Node-RED's settings-user.js as process.env.*, or in the editor
// -> the 'Truma Poller' tab -> Properties -> Environment variables. Without
// TRUMA_MAC the watchdog stays off and only the poller's own backoff applies.
if (!env.get('TRUMA_MAC')) { node.status({ fill: 'grey', shape: 'ring', text: 'set TRUMA_MAC' }); return null }
node.status({ fill: 'yellow', shape: 'dot', text: 'bluetoothctl connect' })
return [{ payload: '' },
        { payload: { lv: 'warn', m: 'BLE watchdog: ' + fails + ' failed reads, last ok '
            + (lastOk ? Math.round(down / 60000) + ' min ago' : 'never') + ' — bluetoothctl connect' } }]

// --- context helpers: use the file store when settings.js provides one, ---
// --- otherwise fall back to memory without throwing.                    ---
function put (k, v) { try { flow.set(k, v, 'file') } catch (e) { flow.set(k, v) } }
function get (k, d) {
  let v; try { v = flow.get(k, 'file') } catch (e) { v = undefined }
  if (v === undefined) v = flow.get(k)
  return v === undefined ? d : v
}
// Result of `select <adapter>` + `connect <mac>` piped into bluetoothctl
// (exec node timer: 25 s). Piped bluetoothctl exits 0 whatever happened, so
// only its own text counts. TRUMA_BLE_ADAPTER selects the USB adapter the
// patched Truma node uses (venus/patches/truma-inetx-adapter); unset, the
// 'select' line is ignored and the default controller is used, as before.
const out = String(msg.payload || '')
const rc = msg.rc ? msg.rc.code : undefined
const ok = /Connection successful|already connected/i.test(out)
if (ok) {
  const conn = get('conn', {})
  conn.fails = 0; conn.backoffUntil = 0; conn.breaker = 'closed'
  put('conn', conn)
  node.status({ fill: 'green', shape: 'dot', text: 'connected, reading' })
  return [{ topic: 'force' },
          { payload: { lv: 'info', m: 'BLE watchdog: connect ok, backoff cleared, reading now' } }]
}
node.status({ fill: 'red', shape: 'ring', text: 'connect failed' })
return [null, { payload: { lv: 'warn', m: 'BLE watchdog: connect failed (rc ' + rc + '): '
  + (out.split('\n').filter(Boolean).pop() || 'no output') } }]
